/* Weight layout : [Cin, CoutPerG, Kd, Kh, Kw]
   Input  layout : [N, Cin, Di, Hi, Wi]
   Output layout : [N, Cout, Do, Ho, Wo]
*/
template<bool WITH_BIAS>
__global__
__launch_bounds__(256, 4)
void conv_transpose3d_kernel(const float *__restrict__ input,
                             const float *__restrict__ weight,
                             const float *__restrict__ bias,
                             float *__restrict__ output,
                             int N, int Cin, int Cout, int groups,
                             int Di, int Hi, int Wi,
                             int Do, int Ho, int Wo,
                             int Kd, int Kh, int Kw,
                             int Sd, int Sh, int Sw,
                             int Pd, int Ph, int Pw,
                             int Od_pad, int Oh_pad, int Ow_pad)
{
    extern __shared__ float s_weight[];   // size = cin_per_group * Kd * Kh * Kw

    const int oc            = blockIdx.x;   // output channel
    const int n             = blockIdx.y;   // batch idx
    const int od            = blockIdx.z;   // output depth position

    const int oc_per_group  = Cout / groups;
    const int cin_per_group = Cin  / groups;

    const int g             = oc / oc_per_group;
    const int oc_in_group   = oc - g * oc_per_group;

    const int Ksize         = Kd * Kh * Kw;
    const int weights_per_oc = cin_per_group * Ksize;

    /* --------------------  load weights into shared ----------------------- */
    const size_t w_base = (((size_t)g * cin_per_group) * oc_per_group + oc_in_group) * Ksize;

    // vectorised copy for better bandwidth
    float4 *s_weight_v4 = reinterpret_cast<float4*>(s_weight);
    const float4 *w_global_v4 = reinterpret_cast<const float4*>(weight + w_base);

    int v4_cnt = weights_per_oc >> 2;          // /4
    for (int idx = threadIdx.x; idx < v4_cnt; idx += blockDim.x) {
        s_weight_v4[idx] = w_global_v4[idx];
    }
    // handle remaining 0-3 floats
    if ((threadIdx.x == 0) && (weights_per_oc & 3)) {
        int tail_start = (v4_cnt << 2);
        for (int t = 0; t < (weights_per_oc & 3); ++t) {
            s_weight[tail_start + t] = weight[w_base + tail_start + t];
        }
    }
    __syncthreads();

    /* -------------------- prepare constants ------------------------------ */
    const float bias_val = WITH_BIAS ? bias[oc] : 0.0f;

    const int kd_start = (od + Pd) % Sd;   // kd satisfying stride condition
    const size_t plane_size = (size_t)Ho * Wo;

    /* -------------------- compute output plane --------------------------- */
    for (size_t plane_idx = threadIdx.x; plane_idx < plane_size; plane_idx += blockDim.x) {
        const int ow = plane_idx % Wo;
        const int oh = plane_idx / Wo;

        float acc = bias_val;

        const int kh_start = (oh + Ph) % Sh;
        const int kw_start = (ow + Pw) % Sw;

        // iterate over depth kernel with stride skipping
        for (int kd = kd_start; kd < Kd; kd += Sd) {
            int id = (od + Pd - kd) / Sd;
            if (id < 0 || id >= Di) continue;

            // iterate over height kernel
            for (int kh = kh_start; kh < Kh; kh += Sh) {
                int ih = (oh + Ph - kh) / Sh;
                if (ih < 0 || ih >= Hi) continue;

                // iterate over width kernel
                for (int kw = kw_start; kw < Kw; kw += Sw) {
                    int iw = (ow + Pw - kw) / Sw;
                    if (iw < 0 || iw >= Wi) continue;

                    const int k_offset = (kd * Kh + kh) * Kw + kw;

                    #pragma unroll
                    for (int icg = 0; icg < cin_per_group; ++icg) {
                        const float w_val = s_weight[icg * Ksize + k_offset];

                        const size_t in_off =
                            (((((size_t)n * Cin + g * cin_per_group + icg) * Di + id) * Hi + ih) * Wi + iw);

                        const float in_val = input[in_off];
                        acc += in_val * w_val;
                    }
                }
            }
        }

        const size_t out_off =
            (((((size_t)n * Cout + oc) * Do + od) * Ho + oh) * Wo + ow);
        output[out_off] = acc;
    }
}

