__device__ inline float relu_scalar(float x) { return x > 0.f ? x : 0.f; }

__global__ __launch_bounds__(THREADS_PER_BLOCK, 2)
void relu_kernel(const float* __restrict__ in,
                 float* __restrict__ out,
                 size_t N)
{
    constexpr int VEC = 4;                  // processing 4 floats at once
    const size_t vecN = N / VEC;            // number of float4 elements
    const float4* in4 = reinterpret_cast<const float4*>(in);
    float4*       out4 = reinterpret_cast<float4*>(out);

    /* Vectorized body ------------------------------------------------------ */
    for (size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
         idx < vecN;
         idx += gridDim.x * blockDim.x)
    {
        float4 v = in4[idx];
        v.x = v.x > 0.f ? v.x : 0.f;
        v.y = v.y > 0.f ? v.y : 0.f;
        v.z = v.z > 0.f ? v.z : 0.f;
        v.w = v.w > 0.f ? v.w : 0.f;
        out4[idx] = v;
    }

    /* Scalar tail ---------------------------------------------------------- */
    const size_t processed = vecN * VEC;
    for (size_t idx = processed + blockIdx.x * blockDim.x + threadIdx.x;
         idx < N;
         idx += gridDim.x * blockDim.x)
    {
        out[idx] = relu_scalar(in[idx]);
    }
}

