    const size_t batch = 16;
    const size_t dim   = 16384;
    const size_t N     = batch * dim;
    const size_t bytes = N * sizeof(float);

    /* Initialize host data ------------------------------------------------- */
    std::vector<float> h_in(N), h_out(N);
    for (size_t i = 0; i < N; ++i)
        h_in[i] = static_cast<float>((rand() % 2000 - 1000) / 1000.0f);

    /* Allocate device buffers --------------------------------------------- */
    float *d_in = nullptr, *d_out = nullptr;
    HIP_CHECK(hipMalloc(&d_in,  bytes));
    HIP_CHECK(hipMalloc(&d_out, bytes));

    HIP_CHECK(hipMemcpy(d_in, h_in.data(), bytes, hipMemcpyHostToDevice));

    /* Kernel launch configuration ----------------------------------------- */
    const size_t vecN   = (N + 3) / 4;                       // ceil(N/4)
    size_t blocks       = (vecN + THREADS_PER_BLOCK - 1) / THREADS_PER_BLOCK;
    const int maxBlocks = 1024;                              // safety cap
    if (blocks > maxBlocks) blocks = maxBlocks;

    hipLaunchKernelGGL(relu_kernel,
                       dim3(blocks),
                       dim3(THREADS_PER_BLOCK),
                       0, 0,
                       d_in, d_out, N);
    HIP_CHECK(hipGetLastError());
    HIP_CHECK(hipDeviceSynchronize());

    /* Copy back & verify --------------------------------------------------- */
    HIP_CHECK(hipMemcpy(h_out.data(), d_out, bytes, hipMemcpyDeviceToHost));

    bool ok = true;
    for (size_t i = 0; i < N; ++i) {
        float ref = h_in[i] > 0.f ? h_in[i] : 0.f;
        if (fabsf(ref - h_out[i]) > 1e-5f) {
