static constexpr int BLOCK_SIZE = 256;

__global__ __launch_bounds__(BLOCK_SIZE, 4)
void swish_kernel(const float *__restrict__ x,
                  float *__restrict__ y,
                  int n) {
  int idx = blockIdx.x * blockDim.x + threadIdx.x;
  int stride = gridDim.x * blockDim.x;

  // Grid-stride loop ensures full utilization even when n is large
  for (int i = idx; i < n; i += stride) {
    float v = x[i];
    // Use fast intrinsic expf for performance; accuracy is sufficient for Swish
    float s = 1.0f / (1.0f + __expf(-v));
    y[i] = v * s;
  }
}

void swish_gpu(const float *h_in, float *h_out, int n) {
  float *d_in = nullptr, *d_out = nullptr;
  size_t bytes = static_cast<size_t>(n) * sizeof(float);

  HIP_CHECK(hipMalloc(&d_in, bytes));
  HIP_CHECK(hipMalloc(&d_out, bytes));

  HIP_CHECK(hipMemcpy(d_in, h_in, bytes, hipMemcpyHostToDevice));

  int grid = (n + BLOCK_SIZE - 1) / BLOCK_SIZE;
  // Cap grid size to maximum allowed blocks
  hipDeviceProp_t prop;
  HIP_CHECK(hipGetDeviceProperties(&prop, 0));
  grid = std::min(grid, prop.multiProcessorCount * 8); // ~8 waves/CU

  hipLaunchKernelGGL(swish_kernel,
                     dim3(grid),
                     dim3(BLOCK_SIZE),
                     0, 0,
                     d_in, d_out, n);
  HIP_CHECK(hipGetLastError());
  HIP_CHECK(hipDeviceSynchronize());

  HIP_CHECK(hipMemcpy(h_out, d_out, bytes, hipMemcpyDeviceToHost));

  HIP_CHECK(hipFree(d_in));
  HIP_CHECK(hipFree(d_out));
}

