    for (int i = 0; i < dim1; ++i) {
        const float4* p = reinterpret_cast<const float4*>(
            src + batchOffset + static_cast<size_t>(i) * dim2 + colStart);
        float4 v = *p;               // coalesced 16-byte load
        acc.x += v.x;
        acc.y += v.y;
        acc.z += v.z;
        acc.w += v.w;
    }

    float* out = dst + static_cast<size_t>(b) * dim2 + colStart;
    if (colStart + 0 < dim2) out[0] = acc.x;
    if (colStart + 1 < dim2) out[1] = acc.y;
    if (colStart + 2 < dim2) out[2] = acc.z;
