            std::cerr << "Mismatch at " << idx
                      << " GPU: " << h_out[idx]
                      << " CPU: " << h_ref[idx] << std::endl;
            return EXIT_FAILURE;
        }
    }
    std::cout << "PASS\n";

    HIP_CHECK(hipFree(d_in));
    HIP_CHECK(hipFree(d_out));
    return 0;
}

