// -----------------------------------------------------------------------------
// Kernel configuration
// -----------------------------------------------------------------------------
constexpr int THREADS_PER_BLOCK   = 256;   // four full wavefronts
constexpr int FLOATS_PER_THREAD   = 4;     // one float4 per thread
constexpr int CHUNK_FLOATS        = THREADS_PER_BLOCK * FLOATS_PER_THREAD; // 1024
// -----------------------------------------------------------------------------
// GPU kernel
// -----------------------------------------------------------------------------
__global__ __launch_bounds__(THREADS_PER_BLOCK, 2)
void diag_row_scale_kernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float*       __restrict__ C,
                           int N, int M)
{
    const int row        = blockIdx.y;
    const int chunkStart = blockIdx.x * CHUNK_FLOATS;   // first column this block handles

    if (row >= N || chunkStart >= M) return;

    const float  a_val   = A[row];
    const size_t baseIdx = static_cast<size_t>(row) * M + chunkStart;
    const float* srcBase = B + baseIdx;
    float*       dstBase = C + baseIdx;

    const int tid = threadIdx.x;

    // -------------------------------------------------------------------------
    // Fast path: whole chunk fits in the row -> fully vectorised float4 access
    // -------------------------------------------------------------------------
    if (chunkStart + CHUNK_FLOATS <= M) {
        const float4* src4 = reinterpret_cast<const float4*>(srcBase);
        float4*       dst4 = reinterpret_cast<float4*>(dstBase);

        float4 v = src4[tid];   // one float4 per thread
        v.x *= a_val;
        v.y *= a_val;
        v.z *= a_val;
        v.w *= a_val;
        dst4[tid] = v;
    }
    // -------------------------------------------------------------------------
    // Tail path: chunk smaller than CHUNK_FLOATS -> scalar path with bounds check
    // -------------------------------------------------------------------------
    else {
        const int remaining = M - chunkStart;
        for (int col = tid; col < remaining; col += blockDim.x) {
            dstBase[col] = a_val * srcBase[col];
        }
    }
}

// -----------------------------------------------------------------------------
// Host-side launcher
// -----------------------------------------------------------------------------
void launch_diag_row_scale(const float* dA,
                           const float* dB,
                           float*       dC,
                           int N, int M,
                           hipStream_t stream = nullptr)
{
    const int gridX = (M + CHUNK_FLOATS - 1) / CHUNK_FLOATS;  // chunks per row
    dim3 block(THREADS_PER_BLOCK);
    dim3 grid(gridX, N);
    hipLaunchKernelGGL(diag_row_scale_kernel,
                       grid, block, 0, stream,
                       dA, dB, dC, N, M);
}

