constexpr int WAVE_SIZE   = 64;
constexpr int BLOCK_SIZE  = 256;   // 4 full waves

//------------------------------------------------------------------------------
// Warp-level reduction helpers (gfx942 wavefront = 64)
//------------------------------------------------------------------------------
__device__ inline float warp_reduce_max(float v)
{
#pragma unroll
    for (int offset = WAVE_SIZE >> 1; offset > 0; offset >>= 1)
        v = fmaxf(v, __shfl_xor(v, offset));
    return v;
}

__device__ inline float warp_reduce_sum(float v)
{
#pragma unroll
    for (int offset = WAVE_SIZE >> 1; offset > 0; offset >>= 1)
        v += __shfl_xor(v, offset);
    return v;
}

//------------------------------------------------------------------------------
// LogSoftmax dim-1 kernel (batch x dim)   dim must be the fastest index
//------------------------------------------------------------------------------
__launch_bounds__(BLOCK_SIZE, 4)
__global__ void logsoftmax_dim1_kernel(const float* __restrict__ in,
                                       float* __restrict__ out,
                                       int dim)
{
    const int  row      = blockIdx.x;
    const int  tid      = threadIdx.x;
    const int  lane_id  = tid & (WAVE_SIZE - 1);      // 0-63
    const int  wave_id  = tid >> 6;                   // 0-3  (4 waves per block)

    const float* row_in  = in  + static_cast<size_t>(row) * dim;
    float*       row_out = out + static_cast<size_t>(row) * dim;

    // -----------------------------------------------------------------------
    // Pass 1: compute per-row maximum
    // -----------------------------------------------------------------------
    float local_max = -FLT_MAX;
    for (int idx = tid; idx < dim; idx += BLOCK_SIZE)
        local_max = fmaxf(local_max, row_in[idx]);

    // Wave reduction
    float wave_max = warp_reduce_max(local_max);

    // Shared scratch for inter-wave reduction
    __shared__ float smem[BLOCK_SIZE / WAVE_SIZE];   // 4 floats
    if (lane_id == 0)
        smem[wave_id] = wave_max;
    __syncthreads();

    // First wave finalises block reduction
    float row_max = -FLT_MAX;
    if (wave_id == 0) {
        float v = (tid < (BLOCK_SIZE / WAVE_SIZE)) ? smem[lane_id] : -FLT_MAX;
        row_max = warp_reduce_max(v);
        if (lane_id == 0)
            smem[0] = row_max;
    }
    __syncthreads();
    row_max = smem[0];

    // -----------------------------------------------------------------------
    // Pass 2: accumulate exp(diff) and buffer diff in registers
    // -----------------------------------------------------------------------
    float local_sum = 0.f;
    // Each thread processes elements in chunks; we use a simple fixed-size
    // stack buffer (max dim / BLOCK_SIZE = 64 when dim = 16384)
    float diff_buf[64];                 // 64 * 256 threads = 16384 elements
    int   buf_cnt = 0;

    for (int idx = tid; idx < dim; idx += BLOCK_SIZE) {
        float diff = row_in[idx] - row_max;
        diff_buf[buf_cnt++] = diff;
        local_sum += __expf(diff);
    }

    // Wave reduction for sum
    float wave_sum = warp_reduce_sum(local_sum);

    if (lane_id == 0)
        smem[wave_id] = wave_sum;
    __syncthreads();

    float row_sum = 0.f;
    if (wave_id == 0) {
        float v = (tid < (BLOCK_SIZE / WAVE_SIZE)) ? smem[lane_id] : 0.f;
        row_sum = warp_reduce_sum(v);
        if (lane_id == 0)
            smem[0] = row_sum;
    }
    __syncthreads();
    row_sum = smem[0];
    const float log_sum = logf(row_sum);

    // -----------------------------------------------------------------------
    // Pass 3: write final outputs using buffered diffs
    // -----------------------------------------------------------------------
    buf_cnt = 0;
    for (int idx = tid; idx < dim; idx += BLOCK_SIZE)
        row_out[idx] = diff_buf[buf_cnt++] - log_sum;
}

