int main()
{
    const int batch = 16;
    const int dim   = 16384;

    const size_t elements = static_cast<size_t>(batch) * dim;
    const size_t bytes    = elements * sizeof(float);

    float* h_in  = static_cast<float*>(malloc(bytes));
    float* h_out = static_cast<float*>(malloc(bytes));

    // Init host data
    for (size_t i = 0; i < elements; ++i)
        h_in[i] = static_cast<float>(rand()) / static_cast<float>(RAND_MAX) * 2.0f - 1.0f;

    float *d_in, *d_out;
    CHECK(hipMalloc(&d_in,  bytes));
    CHECK(hipMalloc(&d_out, bytes));
    CHECK(hipMemcpy(d_in, h_in, bytes, hipMemcpyHostToDevice));

    dim3 grid(batch);
    dim3 block(BLOCK_SIZE);

    hipLaunchKernelGGL(logsoftmax_dim1_kernel, grid, block, 0, 0, d_in, d_out, dim);
    CHECK(hipDeviceSynchronize());

    CHECK(hipMemcpy(h_out, d_out, bytes, hipMemcpyDeviceToHost));

    // Quick correctness check on first row
    {
        float ref_max = -FLT_MAX;
        for (int j = 0; j < dim; ++j)
            ref_max = fmaxf(ref_max, h_in[j]);

        float ref_sum = 0.f;
        for (int j = 0; j < dim; ++j)
            ref_sum += expf(h_in[j] - ref_max);
        float ref_log = logf(ref_sum);

        bool ok = true;
        for (int j = 0; j < dim; ++j) {
            float ref = h_in[j] - ref_max - ref_log;
            if (fabsf(ref - h_out[j]) > 1e-4f) {
                printf("Mismatch at col %d: ref %.6f, got %.6f\n", j, ref, h_out[j]);
                ok = false; break;
            }
        }
        if (ok)
            printf("Kernel finished successfully.\n");
    }

    CHECK(hipFree(d_in));
    CHECK(hipFree(d_out));
    free(h_in);
    free(h_out);
    return EXIT_SUCCESS;
}
